import { readFileSync, writeFileSync } from "node:fs";
import { execSync } from "node:child_process";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { defineConfig } from "@rspack/cli";
import {
	rspack,
	type Mode,
	type RspackOptions,
	type WebpackCompiler,
} from "@rspack/core";

const __dirname = fileURLToPath(new URL(".", import.meta.url));

function extractRuntimeExportNames(source: string): string[] {
	const names = new Set<string>();

	// ESM bundles end with `export { __webpack_exports__X as X, ... };`
	const esmMatches = source.matchAll(/export\s*\{([^}]+)\}\s*;/g);
	for (const m of esmMatches) {
		for (const part of m[1].split(",")) {
			const trimmed = part.trim();
			if (!trimmed) continue;
			const asMatch = trimmed.match(/\s+as\s+([A-Za-z_$][\w$]*)\s*$/);
			const name = asMatch
				? asMatch[1]
				: trimmed.match(/^([A-Za-z_$][\w$]*)/)?.[1];
			if (name) names.add(name);
		}
	}
	if (names.size > 0) return [...names];

	// Webpack IIFE bundles register entry exports via the last
	// `__webpack_require__.d(__webpack_exports__, { ... })` call. In
	// production builds those identifiers get minified, so match any
	// `<ident>.d(<ident>, { ... })` shape.
	const defMatches = [
		...source.matchAll(
			/\b[A-Za-z_$][\w$]*\.d\([A-Za-z_$][\w$]*,\s*\{([\s\S]*?)\}\)/g
		),
	];
	if (defMatches.length > 0) {
		const last = defMatches[defMatches.length - 1][1];
		for (const m of last.matchAll(/([A-Za-z_$][\w$]*)\s*:/g)) {
			names.add(m[1]);
		}
	}
	return [...names];
}

function renderExternalStub(names: string[], globalName: string): string {
	const sorted = [...names].sort();
	return [
		"// AUTO-GENERATED by ExternalStubPlugin - do not edit.",
		`// Re-exports of globalThis.${globalName} (set by the IIFE bundle).`,
		`const __external = /** @type {any} */ (globalThis).${globalName};`,
		"export const {",
		...sorted.map((n) => `\t${n},`),
		"} = __external;",
		"",
	].join("\n");
}

class ExternalStubPlugin {
	bundleFilename: string;
	stubFilename: string;
	globalName: string;
	outputDir: string;

	constructor(opts: {
		bundleFilename: string;
		stubFilename: string;
		globalName: string;
		outputDir: string;
	}) {
		this.bundleFilename = opts.bundleFilename;
		this.stubFilename = opts.stubFilename;
		this.globalName = opts.globalName;
		this.outputDir = opts.outputDir;
	}

	apply(compiler: WebpackCompiler) {
		compiler.hooks.afterEmit.tap("ExternalStubPlugin", () => {
			const bundlePath = join(this.outputDir, this.bundleFilename);
			const stubPath = join(this.outputDir, this.stubFilename);
			let source: string;
			try {
				source = readFileSync(bundlePath, "utf-8");
			} catch {
				console.error("external stub bundle could not be read /ᐠ - ˕ -マ");
				return;
			}

			const names = extractRuntimeExportNames(source);
			if (names.length === 0) {
				console.warn("external stub exports were not found /ᐠ - ˕ -マ");
				return;
			}

			const stub = renderExternalStub(names, this.globalName);
			writeFileSync(stubPath, stub);
			console.log("external stub written!! (˵◝ ⩊  ◜˵マ");
		});
	}
}

const foliodir = join(__dirname, "packages/core");
const controllerdir = join(__dirname, "packages/controller");
const utilsdir = join(__dirname, "packages/utils");

export const tsloader = {
	test: /\.ts$/,
	loader: "builtin:swc-loader",
	exclude: ["/node_modules/"],
	options: {
		jsc: {
			parser: {
				syntax: "typescript",
			},
			target: "es2022",
		},
		module: {
			type: "es6",
			strict: false,
			strictMode: false,
		},
	},
	type: "javascript/auto",
};

function deepmerge<T extends any>(target: T, source: Partial<T>): T {
	// This mirrors the upstream config merge behavior without pulling in more tooling.
	//@ts-ignore dynamic Rspack config merge
	const output = { ...target };
	if (isObject(target) && isObject(source)) {
		Object.keys(source).forEach((key) => {
			//@ts-ignore dynamic Rspack config merge
			if (isObject(source[key])) {
				//@ts-ignore dynamic Rspack config merge
				if (!(key in target)) Object.assign(output, { [key]: source[key] });
				//@ts-ignore dynamic Rspack config merge
				else output[key] = deepmerge(target[key], source[key]);
			} else {
				//@ts-ignore dynamic Rspack config merge
				Object.assign(output, { [key]: source[key] });
			}
		});
	}
	return output;
}

function isObject(item: any): item is Record<string, unknown> {
	return item && typeof item === "object" && !Array.isArray(item);
}

const createGenericConfig = (options: Partial<RspackOptions>) => {
	const production = process.env.NODE_ENV === "production";
	const def = {
		devtool: production ? false : "source-map",
		mode: (production ? "production" : "development") as Mode,
		resolve: {
			extensions: [".ts", ".js"],
		},
		module: {
			rules: [tsloader],
			parser: {
				javascript: {
					overrideStrict: "non-strict",
					dynamicImportMode: "eager",
				},
			},
		},
		optimization: {
			minimizer: [
				new rspack.SwcJsMinimizerRspackPlugin({
					minimizerOptions: {
						module: options.output?.libraryTarget === "module",
					},
				}),
			],
		},
	};
	return defineConfig(deepmerge<RspackOptions>(def as RspackOptions, options));
};

type FolioBuildConfig = {
	entry: RspackOptions["entry"];
	output: RspackOptions["output"];
	rewriterWasm: string;
	extraConfig?: Partial<RspackOptions>;
	name: string;
};

const createFolioConfig = (options: FolioBuildConfig) => {
	const { entry, output, rewriterWasm, extraConfig = {}, name } = options;

	return createGenericConfig({
		name,
		entry,
		resolve: {
			alias: {
				"@rewriters": join(foliodir, "src/shared/rewriters"),
				"@client": join(foliodir, "src/client"),
				"@": join(foliodir, "src"),
			},
		},
		output,
		plugins: [
			new rspack.ProvidePlugin({
				dbg: [join(foliodir, "src/log.ts"), "default"],
			}),
			new rspack.DefinePlugin({
				REWRITERWASM: rewriterWasm,
			}),
			new rspack.DefinePlugin({
				VERSION: JSON.stringify(flpackagemeta.version),
			}),
			new rspack.DefinePlugin({
				COMMITHASH: (() => {
					try {
						return JSON.stringify(
							execSync("git rev-parse --short HEAD", {
								encoding: "utf-8",
								stdio: ["ignore", "pipe", "ignore"],
							}).replace(/\r?\n|\r/g, "")
						);
					} catch {
						return JSON.stringify("unknown");
					}
				})(),
			}),
			new rspack.DefinePlugin({
				BUILDDATE: JSON.stringify(new Date().toISOString()),
			}),
		],
		target: "webworker",
		ignoreWarnings: [
			{
				module: /src\/entry\.ts/,
				message: /Critical dependency: the request of a dependency is an expression/,
			},
		],
		...extraConfig,
	});
};

const flpackagemeta = JSON.parse(
	readFileSync(join(foliodir, "package.json"), "utf-8")
);

const iifeConfig = createFolioConfig({
	name: "folio-iife",
	entry: {
		main: join(foliodir, "src/index.ts"),
	},
	output: {
		filename: "folio.js",
		path: join(foliodir, "dist"),
		iife: true,
		library: {
			type: "assign",
			name: "self.$folio",
		},
	},
	rewriterWasm: "undefined",
	extraConfig: {
		performance: {
			hints: false,
		},
	},
});

const moduleConfig = createFolioConfig({
	name: "folio-esmodule",
	entry: {
		bundle: join(foliodir, "src/index.ts"),
	},
	output: {
		filename: "folio.mjs",
		path: join(foliodir, "dist"),
		libraryTarget: "module",
		iife: false,
	},
	rewriterWasm: "undefined",
	extraConfig: {
		performance: {
			hints: false,
		},
		experiments: {
			outputModule: true,
		},
	},
});
moduleConfig.plugins!.push(
	new ExternalStubPlugin({
		bundleFilename: "folio.mjs",
		stubFilename: "folio-external.mjs",
		globalName: "$folio",
		outputDir: join(foliodir, "dist"),
	})
);

const controllermeta = JSON.parse(
	readFileSync(join(controllerdir, "package.json"), "utf-8")
);
const controllerVersionDefines = new rspack.DefinePlugin({
	FOLIO_EXPECTED_VERSION: JSON.stringify(flpackagemeta.version),
	CONTROLLER_VERSION: JSON.stringify(controllermeta.version),
});

const controllerConfig = createGenericConfig({
	name: "folio-controller",
	dependencies: ["folio-esmodule"],
	entry: {
		api: join(controllerdir, "src/index.ts"),
		inject: join(controllerdir, "src/inject.ts"),
		sw: join(controllerdir, "src/sw.ts"),
	},
	output: {
		filename: "controller.[name].js",
		path: join(controllerdir, "dist"),
		iife: true,
		library: {
			type: "var",
			name: "$folioController",
		},
	},
	target: "web",
	plugins: [
		controllerVersionDefines,
		new ExternalStubPlugin({
			bundleFilename: "controller.api.js",
			stubFilename: "controller-external.mjs",
			globalName: "$folioController",
			outputDir: join(controllerdir, "dist"),
		}),
	],
});

const utilsVersionDefines = new rspack.DefinePlugin({
	FOLIO_EXPECTED_VERSION: JSON.stringify(flpackagemeta.version),
	CONTROLLER_EXPECTED_VERSION: JSON.stringify(controllermeta.version),
});

const utilsIifeConfig = createGenericConfig({
	name: "folio-utils-iife",
	dependencies: ["folio-esmodule", "folio-controller"],
	entry: {
		main: join(utilsdir, "src/index.ts"),
	},
	output: {
		filename: "folio-utils.js",
		path: join(utilsdir, "dist"),
		iife: true,
		library: {
			type: "assign",
			name: "self.$folioUtils",
		},
	},
	target: "web",
	plugins: [
		utilsVersionDefines,
		new ExternalStubPlugin({
			bundleFilename: "folio-utils.js",
			stubFilename: "folio-utils-external.mjs",
			globalName: "$folioUtils",
			outputDir: join(utilsdir, "dist"),
		}),
	],
});

export default [iifeConfig, moduleConfig, controllerConfig, utilsIifeConfig];
